function settingsKey(){return`${course.preset}:${course.seed}:${$('difficulty').value}:${JSON.stringify(settings)}`;}
let savedRuns={};
function readStorage(){try{const raw=localStorage.getItem('aeris.runs.v1');if(raw){const parsed=JSON.parse(raw);if(parsed&&typeof parsed==='object'&&!Array.isArray(parsed))for(const[k,v]of Object.entries(parsed)){try{validateReplay(v);savedRuns[k]=v;}catch{}}}const log=JSON.parse(localStorage.getItem('aeris.log.v1')||'[]');if(Array.isArray(log))flightLog=log.slice(0,30).filter(x=>x&&typeof x==='object'&&typeof x.course==='string'&&typeof x.seed==='string'&&['angle','horizon','acro'].includes(x.mode)&&Number.isFinite(x.time)&&x.time>0&&Number.isFinite(x.penalty)&&x.penalty>=0);}catch{storageOK=false;}}
