function generateCourse(reset=true){course=DroneCore.createCourse($('seed').value.trim()||'2048',$('environment').value);$('seed').value=String(course.seed);$('locationName').textContent=course.name.toUpperCase();$('courseTitle').textContent={canyon:'The canyon circuit',foundry:'The industrial loop',alpine:'The ridge run'}[course.preset];$('courseStats').textContent=`${course.gates.length} GATES · ${Math.round(course.length)} M · FLOW COURSE`;$('presetArt').style.filter=course.preset==='alpine'?'hue-rotate(32deg) saturate(.8)':course.preset==='foundry'?'saturate(.45) brightness(.8)':'';buildWorld();loadBest();if(reset)resetFlight(false);event('course-generated',{seed:course.seed,preset:course.preset});}
function resetFlight(announce=true){phase='ready';drone.reset(course);gateIndex=0;lapTime=0;sectorStart=0;sectors=[];penalty=0;lapStarted=false;recording=[];recordClock=0;recordInterval=.05;simTime=0;ghostTransform=null;replayIndex=0;ghostSample=0;missedCooldown=0;collisionCount=0;graphHistory=[];telemetryClock=0;particles.length=0;accumulator=0;noticeUntil=0;keys.clear();Object.keys(touch).forEach(k=>touch[k]=0);Object.keys(input).forEach(k=>input[k]=0);$('raceResult').hidden=true;updatePhase();if(announce)toast('Flight reset. Same seed. A fresh line.');event('reset',{seed:course.seed});}
function updatePhase(){const ready=phase==='ready',running=phase==='flying',finished=phase==='finished';$('startButton').innerHTML=running?'Ⅱ &nbsp; Pause flight <span class="key">P</span>':phase==='paused'?'▶ &nbsp; Resume flight <span class="key">↵</span>':'▶ &nbsp; Start flight <span class="key">↵</span>';$('readyNote').style.display=ready||phase==='paused'?'flex':'none';$('readyTitle').textContent=phase==='paused'?'Take a breath. Your line can wait.':'Your next great lap starts here.';$('readySubtitle').innerHTML=phase==='paused'?'Press <kbd>Enter</kbd> to resume · <kbd>R</kbd> for a fresh flight':'Press <kbd>Enter</kbd> to arm · <kbd>Space</kbd> to climb · <kbd>W</kbd> to fly';$('liveState').textContent=running?'LIVE':finished?'COMPLETE':phase==='paused'?'PAUSED':'STANDBY';$('raceResult').hidden=!finished;$('recoverButton').disabled=(ready&&session==='trial')||finished;}
function startPause(){if(!renderer||!drone||!course)return;if(phase==='flying')pause();else{if(phase==='finished')resetFlight(false);phase='flying';lapStarted=true;accumulator=0;keys.clear();updatePhase();event('flight-start');if(audio.enabled)audio.start();$('scene').focus({preventScroll:true});}}
function pause(){if(phase==='flying'){phase='paused';keys.clear();Object.keys(input).forEach(k=>input[k]=0);Object.keys(touch).forEach(k=>touch[k]=0);updatePhase();event('pause');}}
function recover(){if(phase==='finished')return resetFlight();if(phase==='ready'&&session==='trial')return toast('Start the time trial before recovering.');const g=course.gates[gateIndex];const recovered=add(g.p,mul(g.normal,-11));recovered[1]=g.p[1];const yaw=Math.atan2(-g.normal[0],-g.normal[2]);drone.recoverAt(recovered,axisQ([0,1,0],yaw));keys.clear();particles.length=0;if(lapStarted&&session==='trial')penalty+=3;flash('RECOVERED · +3.000 s');toast(lapStarted&&session==='trial'?'Recovered before your next gate. +3.000 s penalty.':'Recovered before your next gate.');event('recover',{gate:gateIndex+1,penalty});}
function setCamera(value){camera=value;document.querySelectorAll('[data-camera]').forEach(b=>{const active=b.dataset.camera===value;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});$('cameraLabel').textContent=value.toUpperCase()+' CAMERA';event('camera',{camera});}
function completeRace(){phase='finished';clearTimeout(toast.timer);$('toast').classList.remove('show');const total=lapTime+penalty,newBest=!best||total<best.time;const run={version:1,time:total,duration:lapTime,penalty,sectors:[...sectors],samples:recording.slice(),seed:String(course.seed),preset:course.preset,mode:settings.mode,settings:{...settings},difficulty:$('difficulty').value};if(newBest){savedRuns[settingsKey()]=run;best=run;replay=run;$('ghostHint').textContent=`${timeFormat(total)} · ${run.samples.length} recorded frames`;}flightLog.unshift({course:course.name,seed:String(course.seed),time:total,penalty,mode:settings.mode,date:new Date().toISOString()});flightLog=flightLog.slice(0,30);persist();$('finishTime').textContent=timeFormat(total);$('finishText').textContent=`${newBest?'New local best. Ghost saved.':'A clean finish. Ready for another?'} ${penalty?`Includes ${penalty.toFixed(1)} s in penalties.`:''}`;updatePhase();event('finish',{time:total,newBest,gates:gateIndex,samples:recording.length});audio.beep(660,.22);}
function checkRace(prev){if(session!=='trial'||phase!=='flying')return;const target=course.gates[gateIndex];const hit=DroneCore.crossGate(prev,drone.p,target,drone.radius||.35);if(hit.crossed){const total=lapTime+penalty;sectors.push(total-sectorStart);sectorStart=total;gateIndex++;audio.beep(500+gateIndex*65,.13);flash(gateIndex===course.gates.length?'FINISH LINE':'CHECKPOINT '+String(gateIndex).padStart(2,'0')+' CLEARED',1.7);event('checkpoint',{gate:gateIndex,time:total,p:[...drone.p]});if(gateIndex>=course.gates.length){recordSample(true);completeRace();return;}}else if(hit.missed&&simTime>missedCooldown){flash('MISSED GATE · TURN BACK',3);missedCooldown=simTime+3;event('missed-gate',{gate:gateIndex+1});}else if(simTime>missedCooldown){for(let j=gateIndex+1;j<course.gates.length;j++){if(DroneCore.crossGate(prev,drone.p,course.gates[j],drone.radius||.35).crossed){flash(`OUT OF ORDER · FIND GATE ${gateIndex+1}`,3);missedCooldown=simTime+3;event('out-of-order',{crossed:j+1,expected:gateIndex+1});break;}}}}
function recordSample(force=false){if(session!=='trial'||!lapStarted)return;if(recording.length>=23900){recording=recording.filter((s,i,a)=>i===0||i%2===0||s.gate!==a[i-1].gate||i===a.length-1);recordInterval*=2;}const last=recording[recording.length-1];if(force&&last&&Math.abs(last.t-lapTime)<.001){last.gate=gateIndex;last.p=drone.p.map(x=>+x.toFixed(5));last.q=drone.q.map(x=>+x.toFixed(6));return;}recording.push({t:+lapTime.toFixed(5),p:drone.p.map(x=>+x.toFixed(5)),q:drone.q.map(x=>+x.toFixed(6)),gate:gateIndex});}
function updateGhost(){if(!prefs.ghost||!replay||!lapStarted||!replay.samples.length){ghostTransform=null;return;}const samples=replay.samples,t=clamp(lapTime,0,replay.duration);while(replayIndex<samples.length-2&&samples[replayIndex+1].t<t)replayIndex++;const a=samples[replayIndex],b=samples[Math.min(replayIndex+1,samples.length-1)],f=clamp((t-a.t)/(b.t-a.t||1),0,1),sign=dot(a.q,b.q)<0?-1:1;ghostTransform={p:a.p.map((v,i)=>mix(v,b.p[i],f)),q:norm(a.q.map((v,i)=>mix(v,b.q[i]*sign,f)))};ghostSample=replayIndex;}
function emitCollision(impact){const count=Math.floor((8+impact*2)*prefs.particles);for(let i=0;i<count;i++){const life=.4+Math.random()*.8;particles.push({p:add(drone.p,[(Math.random()-.5)*.5,-.2,(Math.random()-.5)*.5]),v:[(Math.random()-.5)*impact*.7,Math.random()*impact*.5+1,(Math.random()-.5)*impact*.7],life,max:life,size:.04+Math.random()*.14,kind:i%3===0?'spark':'dust'});}if(particles.length>200)particles.splice(0,particles.length-200);}
function updateParticles(dt){for(let i=particles.length-1;i>=0;i--){const a=particles[i];a.life-=dt;a.v[1]-=4*dt;a.p=add(a.p,mul(a.v,dt));if(a.life<=0)particles.splice(i,1);}}
const audio={ctx:null,enabled:false,osc:[],gain:null,filter:null,start(){try{if(!this.ctx){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('Web Audio unavailable');this.ctx=new AC();this.gain=this.ctx.createGain();this.gain.gain.value=0;this.gain.connect(this.ctx.destination);this.filter=this.ctx.createBiquadFilter();this.filter.type='lowpass';this.filter.frequency.value=1100;this.filter.connect(this.gain);for(let i=0;i<4;i++){const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=i%2?'sawtooth':'triangle';o.frequency.value=100+i*3;g.gain.value=.14;o.connect(g);g.connect(this.filter);o.start();this.osc.push(o);}}this.ctx.resume();this.enabled=true;$('audioButton').textContent='♫  Engine audio enabled';$('audioHint').textContent='Motor pitch follows rotor command; impacts produce a short noise burst.';}catch(e){toast('Audio unavailable: '+e.message,true);}},update(){if(!this.ctx)return;const now=this.ctx.currentTime,m=drone.motor||0;this.gain.gain.setTargetAtTime(this.enabled&&phase==='flying'?prefs.volume*(.08+m*.19):0,now,.08);this.osc.forEach((o,i)=>o.frequency.setTargetAtTime(70+m*360+i*(2+m*5)+len(drone.v)*.4,now,.06));this.filter.frequency.setTargetAtTime(500+m*2300,now,.1);},beep(freq,duration){if(!this.enabled||!this.ctx)return;const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(prefs.volume*.12,this.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,this.ctx.currentTime+duration);o.connect(g);g.connect(this.ctx.destination);o.start();o.stop(this.ctx.currentTime+duration);},impact(power){if(!this.ctx||!this.enabled)return;const count=this.ctx.sampleRate*.22,buffer=this.ctx.createBuffer(1,count,this.ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<count;i++)data[i]=(Math.random()*2-1)*Math.pow(1-i/count,3);const s=this.ctx.createBufferSource(),g=this.ctx.createGain();s.buffer=buffer;g.gain.value=prefs.volume*clamp(power/18,.05,.4);s.connect(g);g.connect(this.ctx.destination);s.start();}};
