const flightKeys=new Set(['Space','ShiftLeft','ShiftRight','KeyW','KeyS','KeyA','KeyD','KeyQ','KeyE','ArrowUp','ArrowDown','ArrowLeft','ArrowRight']);
function keyCode(e){return e.code||({' ':'Space',Shift:'ShiftLeft',Enter:'Enter',Escape:'Escape',ArrowUp:'ArrowUp',ArrowDown:'ArrowDown',ArrowLeft:'ArrowLeft',ArrowRight:'ArrowRight'}[e.key])||(/^[a-z]$/i.test(e.key)?'Key'+e.key.toUpperCase():'');}
