window.addEventListener('keydown',e=>{const code=keyCode(e);if(!renderer||!drone||!course||renderer.lost)return;if(editing(e))return;if($('modalBackdrop').classList.contains('open')){if(code==='Escape')closeModal();return;}if(flightKeys.has(code)){e.preventDefault();if(phase==='flying')keys.add(code);return;}if(e.repeat)return;if(code==='Enter'&&!e.target.closest('button')){e.preventDefault();startPause();}else if(code==='KeyP'||code==='Escape'){e.preventDefault();startPause();}else if(code==='KeyR'){e.preventDefault();resetFlight();}else if(code==='KeyC'){const cams=['fpv','chase','orbit','trackside'];setCamera(cams[(cams.indexOf(camera)+1)%4]);}else if(code==='KeyH')showControls();});
