function setupStick(id,left){const el=$(id),knob=el.querySelector('.knob');let pointer=null;function move(e){if(pointer!==e.pointerId)return;e.preventDefault();const r=el.getBoundingClientRect(),x=clamp((e.clientX-r.left-r.width/2)/(r.width*.36),-1,1),y=clamp((e.clientY-r.top-r.height/2)/(r.height*.36),-1,1);knob.style.transform=`translate(${x*30}px,${y*30}px)`;if(left){touch.yaw=x;touch.throttle=-y;}else{touch.roll=x;touch.pitch=-y;}}function release(e){if(pointer!==e.pointerId)return;pointer=null;knob.style.transform='';if(left)touch.yaw=touch.throttle=0;else touch.roll=touch.pitch=0;}el.addEventListener('pointerdown',e=>{pointer=e.pointerId;el.setPointerCapture(pointer);move(e);});el.addEventListener('pointermove',move);el.addEventListener('pointerup',release);el.addEventListener('pointercancel',release);el.addEventListener('lostpointercapture',release);}
