function range(parent,id,label,min,max,step,value,format,onChange){const d=document.createElement('div');d.className='range-row';d.innerHTML=`<label class="range-label" for="${id}">${label}<output id="${id}Out">${format(value)}</output></label><input type="range" id="${id}" min="${min}" max="${max}" step="${step}" value="${value}">`;$(parent).append(d);$(id).addEventListener('input',()=>{const v=+$(id).value;$(id+'Out').textContent=format(v);onChange(v);});}
