function syncMode(){$('flightMode').value=settings.mode;$('modeDescription').textContent={angle:'Self-leveling attitude control. Release pitch and roll to level; altitude assist helps you hold height.',horizon:'A blended controller: leveling near center and direct angular rates near full stick.',acro:'Manual angular rates. Release the stick to stop rotation, retaining your attitude. Counter-steer to level.'}[settings.mode];$('flightModeFooter').textContent=settings.mode.toUpperCase()+' MODE';$('assistTag').textContent=settings.mode==='acro'?'MANUAL':'ACTIVE';}
function syncSettings(){syncMode();for(const k of Object.keys(settings)){if(k==='mode')continue;const e=$(k);if(e){e.value=settings[k];const unit={gravity:' m/s²',twr:' : 1',rates:'°/s'};$(k+'Out').textContent=['autoLevel','altHold','antiCrash','forgiveness'].includes(k)?Math.round(settings[k]*100)+'%':settings[k].toFixed(k==='rates'?0:['expo','drag'].includes(k)?2:1)+(unit[k]||'');}}}
$('resetTuning').addEventListener('click',()=>{Object.assign(settings,defaults);syncSettings();$('difficulty').value='rookie';$('difficultyBadge').textContent='ROOKIE';loadBest();resetFlight(false);toast('Default flight dynamics restored.');});$('ghostToggle').addEventListener('change',()=>{prefs.ghost=$('ghostToggle').checked;updateGhost();});$('effectsToggle').addEventListener('change',()=>{prefs.effects=$('effectsToggle').checked;$('vignette').style.display=prefs.effects?'block':'none';});$('lighting').addEventListener('change',()=>{prefs.lighting=$('lighting').value;buildWorld();});$('quality').addEventListener('change',()=>{prefs.quality=$('quality').value;prefs.resolution={low:.6,balanced:1,high:1.25}[prefs.quality];prefs.particles={low:.2,balanced:.6,high:1}[prefs.quality];prefs.lighting=prefs.quality==='low'?'low':'high';$('resolution').value=prefs.resolution;$('resolutionOut').textContent=prefs.resolution.toFixed(1)+'×';$('particles').value=prefs.particles;$('particlesOut').textContent=prefs.particles.toFixed(1);$('lighting').value=prefs.lighting;adaptive=1;buildWorld();resize();event('quality',{quality:prefs.quality});});$('diagnosticsToggle').addEventListener('change',()=>{$('diagnostic').hidden=!$('diagnosticsToggle').checked;});$('volume').addEventListener('input',()=>{prefs.volume=+$('volume').value/100;$('volumeOut').textContent=$('volume').value+'%';});$('audioButton').addEventListener('click',()=>{if(audio.enabled){audio.enabled=false;$('audioButton').textContent='♫  Enable engine audio';}else audio.start();});$('deadzone').addEventListener('input',()=>{prefs.deadzone=+$('deadzone').value/100;$('deadzoneOut').textContent=$('deadzone').value+'%';});$('gamepadLayout').addEventListener('change',()=>prefs.layout=$('gamepadLayout').value);document.querySelectorAll('[data-invert]').forEach(e=>e.addEventListener('change',()=>prefs.invert[e.dataset.invert]=e.checked));$('calibrateButton').addEventListener('click',()=>{if(!activeGamepad)return toast('No controller detected. Connect a gamepad and press a button first.',true);prefs.calibration=Array.from({length:4},(_,i)=>activeGamepad.axes[i]||0);toast('Neutral sticks calibrated. Dead zone applied.');event('gamepad-calibrated');});
const limits={gravity:[1,20],twr:[1.4,6],drag:[.05,1.2],rates:[60,600],expo:[0,.85],autoLevel:[0,1],altHold:[0,1],antiCrash:[0,1],forgiveness:[0,1]};
function validateSettings(s){if(!s||typeof s!=='object'||!['angle','horizon','acro'].includes(s.mode))throw Error('Invalid flight mode');for(const[k,[lo,hi]]of Object.entries(limits))if(!Number.isFinite(s[k])||s[k]<lo||s[k]>hi)throw Error('Invalid physics setting: '+k);return Object.fromEntries(Object.keys(defaults).map(k=>[k,s[k]]));}
function validateReplay(r){if(!r||r.version!==1||!Number.isFinite(r.time)||r.time<=0||r.time>172800||!Number.isFinite(r.duration)||r.duration<=0||r.duration>86400||r.time+0.001<r.duration||!Number.isFinite(r.penalty)||r.penalty<0||Math.abs(r.time-r.duration-r.penalty)>.02)throw Error('Invalid replay timing');if(!Array.isArray(r.samples)||r.samples.length<2||r.samples.length>24000)throw Error('Replay must contain 2–24,000 frames');if(!Array.isArray(r.sectors)||r.sectors.length!==8||r.sectors.some(s=>!Number.isFinite(s)||s<=0)||Math.abs(r.sectors.reduce((a,b)=>a+b,0)-r.time)>.03)throw Error('Invalid replay sectors');let t=-1;for(const s of r.samples){if(!s||!Number.isFinite(s.t)||s.t<=t||s.t<0||s.t>r.duration+.01)throw Error('Replay timestamps must be strictly ordered');t=s.t;if(!Array.isArray(s.p)||s.p.length!==3||s.p.some(v=>!Number.isFinite(v)||Math.abs(v)>500)||!Array.isArray(s.q)||s.q.length!==4||s.q.some(v=>!Number.isFinite(v))||Math.abs(len(s.q)-1)>.03||!Number.isInteger(s.gate)||s.gate<0||s.gate>8)throw Error('Invalid replay transform');}if(Math.abs(t-r.duration)>.1)throw Error('Replay is missing its finish');if(typeof r.seed!=='string'||r.seed.length>32||!['canyon','foundry','alpine'].includes(r.preset))throw Error('Invalid replay course');validateSettings(r.settings);if(r.samples[0].t>.1||r.samples[0].gate!==0||r.samples[r.samples.length-1].gate!==8)throw Error('Replay must include the entire ordered course');let lastGate=0;for(const s of r.samples){if(s.gate<lastGate||s.gate>lastGate+1)throw Error('Invalid replay checkpoint order');lastGate=s.gate;}const replayCourse=DroneCore.createCourse(r.seed,r.preset);let reached=0;for(let i=1;i<r.samples.length&&reached<8;i++){if(DroneCore.crossGate(r.samples[i-1].p,r.samples[i].p,replayCourse.gates[reached],0).crossed)reached++;}if(reached!==8)throw Error('Replay route does not pass all checkpoints');return r;}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
$('exportButton').addEventListener('click',()=>{const data={format:'aeris-course',version:1,course:{seed:String(course.seed),preset:course.preset,difficulty:$('difficulty').value},settings:{...settings},replay:best};download(JSON.stringify(data),`aeris-${course.preset}-${String(course.seed).replace(/[^a-z0-9_-]/gi,'_')}.json`,'application/json');event('export',{hasReplay:!!best});toast(best?'Course and best-lap replay exported.':'Course exported. Complete a time trial to include a ghost.');});
$('importButton').addEventListener('click',()=>{$('importFile').value='';$('importFile').click();});
$('importFile').addEventListener('change',async()=>{const file=$('importFile').files[0];if(!file)return;try{if(file.size>6*1024*1024)throw Error('File exceeds 6 MB');const d=JSON.parse(await file.text());if(d.format!=='aeris-course'||d.version!==1||!d.course||typeof d.course.seed!=='string'||!d.course.seed.trim()||d.course.seed.length>32||!['canyon','foundry','alpine'].includes(d.course.preset)||!['rookie','sport','pro'].includes(d.course.difficulty))throw Error('Not a supported AERIS course file');const nextSettings=validateSettings(d.settings);if(d.replay){validateReplay(d.replay);if(d.replay.seed!==d.course.seed||d.replay.preset!==d.course.preset||d.replay.difficulty!==d.course.difficulty||JSON.stringify(validateSettings(d.replay.settings))!==JSON.stringify(nextSettings))throw Error('Replay does not match this course and flight setup');}Object.assign(settings,nextSettings);$('environment').value=d.course.preset;$('seed').value=d.course.seed;$('difficulty').value=d.course.difficulty;$('difficultyBadge').textContent=d.course.difficulty.toUpperCase();syncSettings();generateCourse();if(d.replay){savedRuns[settingsKey()]=d.replay;persist();loadBest();}toast(d.replay?'Course and recorded ghost imported.':'Course imported. Ready to fly.');event('import',{hasReplay:!!d.replay});}catch(e){toast('Import failed: '+e.message,true);event('import-error',{message:e.message});}});
$('screenshotButton').addEventListener('click',()=>{try{renderer.render(performance.now());drawHUD();const w=$('scene').width,h=$('scene').height,c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');ctx.drawImage($('scene'),0,0);ctx.drawImage($('hud'),0,0,w,h);ctx.fillStyle='#101b13c9';ctx.fillRect(0,0,w,48);ctx.fillStyle='#d1f77a';ctx.font='bold 17px monospace';ctx.fillText('AERIS / '+course.name.toUpperCase(),20,30);ctx.textAlign='right';ctx.fillStyle='#e7efd9';ctx.font='12px monospace';ctx.fillText(`${camera.toUpperCase()} · ${settings.mode.toUpperCase()} · ${timeFormat(lapTime+penalty)}`,w-20,29);const a=document.createElement('a');a.download='aeris-flight.png';a.href=c.toDataURL('image/png');a.click();event('screenshot');toast('Flight frame saved as PNG.');}catch(e){toast('Screenshot failed: '+e.message,true);}});
