function openModal(title,html){pause();lastFocused=document.activeElement;$('modalTitle').textContent=title;$('modalContent').innerHTML=html;$('modalBackdrop').classList.add('open');$('closeModal').focus();}
function closeModal(){$('modalBackdrop').classList.remove('open');if(lastFocused)lastFocused.focus({preventScroll:true});}
$('closeModal').addEventListener('click',closeModal);$('modalBackdrop').addEventListener('click',e=>{if(e.target===$('modalBackdrop'))closeModal();});$('modalBackdrop').addEventListener('keydown',e=>{if(e.code==='Escape')closeModal();if(e.code==='Tab'){const els=Array.from($('modalBackdrop').querySelectorAll('button,a,input,select')).filter(e=>!e.disabled);const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
function showControls(){openModal('Find your flow.',`<div class="eyebrow" style="color:var(--lime)">A QUICK PREFLIGHT</div><p>Start in Angle mode. Arm the motors, hold Space until you reach about 4 m, then gently pitch forward with W. Release W to level. Fly through the lime gates in order.</p><div class="keyboard-grid"><div><kbd>W</kbd><kbd>S</kbd><span>Pitch forward / back</span></div><div><kbd>A</kbd><kbd>D</kbd><span>Roll left / right</span></div><div><kbd>Q</kbd><kbd>E</kbd><span>Yaw left / right</span></div><div><kbd>Space</kbd><kbd>Shift</kbd><span>Climb / descend</span></div><div><kbd>Enter</kbd><kbd>P</kbd><span>Arm / pause</span></div><div><kbd>R</kbd><span>Deterministic restart</span></div><div><kbd>C</kbd><span>Switch camera</span></div><div><kbd>H</kbd><span>This flight guide</span></div></div><h3>Fly the craft. Feel the momentum.</h3><p>Your motors tilt with the airframe. Banking creates acceleration; releasing the stick levels an assisted craft, but momentum remains. Pitch backward to brake. Recover returns you before the next gate with a 3-second penalty. Collisions add 2 seconds.</p><h3>Controller & touch</h3><p>Connect a gamepad and press any button. The Input tab provides neutral calibration, dead zone and inversion. On a phone, the left stick controls throttle/yaw and the right stick controls pitch/roll.</p><div class="modal-actions"><button class="primary" id="guideDone">Ready for takeoff ↗</button></div>`);$('guideDone').onclick=closeModal;}
$('helpButton').onclick=showControls;$('footerControls').onclick=showControls;$('navFlight').onclick=()=>{closeModal();$('scene').focus({preventScroll:true});};$('navHangar').onclick=()=>openModal('Small frame. Big possibilities.',`<div class="eyebrow" style="color:var(--lime)">AERIS / R-5 FREESTYLE QUAD</div><svg viewBox="0 0 450 155" style="width:100%;height:155px;margin:18px 0" aria-label="Quadcopter plan view"><g fill="none" stroke="#677952" stroke-width="5"><path d="M145 35l160 90M145 125l160-90"/></g><g fill="#c9ef7755" stroke="#d1f77a" stroke-width="1.5"><ellipse cx="145" cy="35" rx="43" ry="20"/><ellipse cx="305" cy="35" rx="43" ry="20"/><ellipse cx="145" cy="125" rx="43" ry="20"/><ellipse cx="305" cy="125" rx="43" ry="20"/></g><rect x="206" y="44" width="38" height="70" rx="8" fill="#66794b" stroke="#d1f77a"/><rect x="214" y="34" width="22" height="16" rx="4" fill="#142115" stroke="#d1f77a"/><circle cx="225" cy="39" r="5" fill="#c9ef77"/></svg><div class="spec-grid"><div><span>FRAME</span><b>5 inch</b></div><div><span>ALL-UP MASS</span><b>700 g</b></div><div><span>THRUST / WEIGHT</span><b>${settings.twr.toFixed(1)} : 1</b></div></div><p>A responsive quad with motor spool-up, body-frame thrust, gravity, aerodynamic drag and angular inertia. Its 120 Hz flight model powers every camera and every instrument.</p><h3>Three ways to fly</h3><p><b>Angle</b> holds a bank angle and levels when released. <b>Horizon</b> blends leveling with manual rates. <b>Acro</b> follows your angular rate commands for full attitude control.</p>`);
